-- PoisonBench evaluation logging schema (generated by evaluation/store.py)
CREATE TABLE IF NOT EXISTS eval_runs (
    run_id TEXT,
    group_name TEXT,
    config_name TEXT,
    config_json TEXT,
    attack_type TEXT,
    poisoning_ratio DOUBLE PRECISION,
    seed INTEGER,
    source_name TEXT,
    n_queries INTEGER,
    context_size INTEGER,
    n_retrieve INTEGER,
    generation_enabled INTEGER,
    created_at TEXT,
    n_poison_candidates INTEGER,
    attack_success_raw DOUBLE PRECISION,
    attack_success_defended DOUBLE PRECISION,
    attack_success_generation DOUBLE PRECISION,
    security_blocked_pct DOUBLE PRECISION,
    detection_rate DOUBLE PRECISION,
    fpr DOUBLE PRECISION,
    fpr_block DOUBLE PRECISION,
    clean_retention DOUBLE PRECISION,
    latency_ms_mean DOUBLE PRECISION,
    latency_ms_p95 DOUBLE PRECISION,
    router_high_fraction DOUBLE PRECISION,
    PRIMARY KEY (run_id)
);

CREATE TABLE IF NOT EXISTS eval_query_results (
    run_id TEXT,
    query_id TEXT,
    n_candidates INTEGER,
    n_poison_candidates INTEGER,
    raw_poison_in_context INTEGER,
    defended_poison_in_context INTEGER,
    raw_success INTEGER,
    defended_success INTEGER,
    gen_success INTEGER,
    poison_blocked INTEGER,
    poison_flagged INTEGER,
    clean_seen INTEGER,
    clean_blocked INTEGER,
    clean_flagged INTEGER,
    clean_retention DOUBLE PRECISION,
    total_latency_ms DOUBLE PRECISION,
    PRIMARY KEY (run_id, query_id)
);

CREATE TABLE IF NOT EXISTS eval_stage_logs (
    run_id TEXT,
    query_id TEXT,
    stage TEXT,
    position INTEGER,
    n_in INTEGER,
    n_blocked INTEGER,
    n_flagged INTEGER,
    latency_ms DOUBLE PRECISION,
    poison_in INTEGER,
    poison_blocked INTEGER,
    poison_flagged INTEGER,
    clean_in INTEGER,
    clean_blocked INTEGER,
    clean_flagged INTEGER,
    routed_high INTEGER,
    routed_low INTEGER,
    PRIMARY KEY (run_id, query_id, position)
);

CREATE TABLE IF NOT EXISTS eval_chunk_scores (
    run_id TEXT,
    query_id TEXT,
    chunk_id TEXT,
    is_poisoned INTEGER,
    attack_type TEXT,
    poisoning_ratio DOUBLE PRECISION,
    seed INTEGER,
    similarity DOUBLE PRECISION,
    d1_z DOUBLE PRECISION,
    d1_flagged INTEGER,
    d1_blocked INTEGER,
    d2_suspicion DOUBLE PRECISION,
    d2_flagged INTEGER,
    d3_suspicion DOUBLE PRECISION,
    d3_flagged INTEGER,
    d3_blocked INTEGER,
    d4_prob DOUBLE PRECISION,
    risk_score DOUBLE PRECISION,
    PRIMARY KEY (run_id, query_id, chunk_id)
);

CREATE TABLE IF NOT EXISTS eval_false_positives (
    run_id TEXT,
    query_id TEXT,
    chunk_id TEXT,
    stage TEXT,
    action TEXT,
    suspicion DOUBLE PRECISION,
    PRIMARY KEY (run_id, query_id, chunk_id, stage, action)
);
